import {
    FileSystem,
    isSupportedNode,
    ts,
    path,
    type Plugin,
    type Transform as ITransform,
    type Result,
    Shape,
    type Database,
    type Record,
    type File,
    isFluentNode,
    getUnsupportedKindName,
    type PluginUsageTracker,
} from '@servicenow/sdk-build-core'
import { Project } from '../project'

class Transform implements ITransform {
    constructor(
        private readonly project: Project,
        private readonly pluginUsageTracker: PluginUsageTracker
    ) {}

    private async shapeToSubclass<const S extends Shape>(
        shape: S,
        plugins: Plugin[]
    ): Promise<{ success: true; value: S }> {
        for (const plugin of plugins.length > 0 ? plugins : this.project.getPlugins().toArray()) {
            try {
                const result = await plugin.shapeToSubclass(shape, this.project.getContext())
                if (result.success) {
                    return await this.shapeToSubclass(result.value, plugins)
                }
            } catch (error) {
                this.project
                    .getLogger()
                    .error(`Plugin "${plugin.getName()}" failed to subclass "${shape.getKind()}" shape:`, error)
            }
        }

        return { success: true, value: shape }
    }

    private async shapeToRecord(shape: Shape, plugins: Plugin[]): Promise<Result<Record>> {
        if (shape.isRecord()) {
            return { success: true, value: shape }
        }

        for (const plugin of plugins.length > 0 ? plugins : this.project.getPlugins().toArray()) {
            try {
                const result = await plugin.shapeToRecord(shape, this.project.getContext())
                if (result.success) {
                    this.pluginUsageTracker.addPluginToRecordUsage(plugin, shape, result.value.getCount())
                    return {
                        success: true,
                        value: result.value,
                    }
                }
            } catch (error) {
                this.project
                    .getLogger()
                    .error(
                        `Plugin "${plugin.getName()}" failed to transform "${shape.getKind()}" shape into record:`,
                        error
                    )
            }
        }

        return { success: false }
    }

    private async nodeToRecord(node: ts.Node, plugins: Plugin[]): Promise<Result<Record>> {
        const shapeResult = await this.toShape(node, ...plugins)
        return shapeResult.success ? this.shapeToRecord(shapeResult.value, plugins) : shapeResult
    }

    private async fileToRecord(file: File, plugins: Plugin[]): Promise<Result<Record>> {
        for (const plugin of plugins.length > 0 ? plugins : this.project.getPlugins().toArray()) {
            try {
                const result = await plugin.fileToRecord(file, this.project.getContext())
                if (result.success) {
                    this.pluginUsageTracker.addPluginToRecordUsage(plugin, file, result.value.getCount())
                    return {
                        success: true,
                        value: result.value,
                    }
                }
            } catch (error) {
                this.project
                    .getLogger()
                    .error(`Plugin "${plugin.getName()}" failed to transform "${file.path}" into records:`, error)
            }
        }

        return { success: false }
    }

    async toRecord(source: ts.Node | Shape | File, ...plugins: Plugin[]): Promise<Result<Record>> {
        if (ts.Node.isNode(source)) {
            return this.nodeToRecord(source, plugins)
        } else if (source instanceof Shape) {
            return this.shapeToRecord(source, plugins)
        } else {
            return this.fileToRecord(source, plugins)
        }
    }

    async toShape(node: ts.Node, ...plugins: Plugin[]): Promise<Result<Shape>> {
        const diagnostics = this.project.getDiagnosticsService()
        if (!isSupportedNode(node)) {
            if (isFluentNode(node)) {
                diagnostics.error(node, `Node kind "${getUnsupportedKindName(node)}" is not allowed in Fluent files.`)
            }

            return { success: false }
        }

        for (const plugin of plugins.length > 0 ? plugins : this.project.getPlugins().toArray()) {
            try {
                // First, try to parse the node into a shape
                const shapeResult = await plugin.nodeToShape(node, this.project.getContext())

                // Then, let plugins try to produce a subclass for this shape
                const subclassResult = shapeResult.success
                    ? await this.shapeToSubclass(shapeResult.value, plugins)
                    : shapeResult

                // Then, let plugins try to turn the subclassed shape into a record
                const recordResult = subclassResult.success
                    ? await this.toRecord(subclassResult.value, ...plugins)
                    : subclassResult

                // The final result is the record if we got one, otherwise just the subclassed shape
                const result = recordResult.success ? recordResult : subclassResult
                if (result.success) {
                    return result
                }
            } catch (error) {
                this.project
                    .getLogger()
                    .error(
                        `Plugin "${plugin.getName()}" failed to transform "${node.getKindName()}" node into shape:`,
                        error
                    )
            }
        }

        return { success: false }
    }

    async recordToShape(record: Record, database: Database, ...plugins: Plugin[]): Promise<Result<Shape>> {
        for (const plugin of plugins.length > 0 ? plugins : this.project.getPlugins().toArray()) {
            const result = await plugin.recordToShape({
                record,
                database,
                context: this.project.getContext(),
            })
            if (result.success) {
                return result
            }
        }
        return { success: false }
    }

    async toSubclass<const S extends Shape>(shape: S, ...plugins: Plugin[]): Promise<Result<S>> {
        return this.shapeToSubclass(shape, plugins)
    }

    async getUpdateName(record: Record, ...plugins: Plugin[]): Promise<string> {
        for (const plugin of plugins.length > 0 ? plugins : this.project.getPlugins().toArray()) {
            try {
                const result = await plugin.getUpdateName(record, this.project.getContext())
                if (result.success) {
                    return result.value
                }
            } catch (error) {
                this.project
                    .getLogger()
                    .error(
                        `Plugin "${plugin.getName()}" failed to get update name for record: ${record.getTable()}`,
                        error
                    )
            }
        }

        throw new Error(`Failed to get update name for record: ${record.getTable()}`)
    }
}

export class MultiProjectTransform implements ITransform {
    private fallbackTransform?: ITransform
    private readonly rootTransform: ITransform
    private readonly transformMap: globalThis.Record<string, ITransform> = {}

    constructor(
        private readonly rootProject: Project,
        private readonly pluginUsageTracker: PluginUsageTracker
    ) {
        this.rootTransform = new Transform(rootProject, this.pluginUsageTracker)
        this.transformMap[rootProject.getRootDir()] = this.rootTransform
    }

    toRecord(source: ts.Node | Shape | File, ...plugins: Plugin[]): Promise<Result<Record>> {
        return this.getTransformForPath(
            ts.Node.isNode(source)
                ? source.getSourceFile().getFilePath()
                : source instanceof Shape
                  ? source.getOriginalFilePath()
                  : source.path
        ).toRecord(source, ...plugins)
    }

    async toShape(node: ts.Node, ...plugins: Plugin[]): Promise<Result<Shape>> {
        return this.getTransformForPath(node.getSourceFile().getFilePath()).toShape(node, ...plugins)
    }

    async recordToShape(record: Record, database: Database, ...plugins: Plugin[]): Promise<Result<Shape>> {
        return this.getTransformForPath(record.getOriginalFilePath()).recordToShape(record, database, ...plugins)
    }

    async toSubclass<const S extends Shape>(shape: S, ...plugins: Plugin[]): Promise<Result<S>> {
        return this.getTransformForPath(shape.getOriginalFilePath()).toSubclass(shape, ...plugins)
    }

    async getUpdateName(record: Record, ...plugins: Plugin[]): Promise<string> {
        return this.getTransformForPath(record.getOriginalFilePath()).getUpdateName(record, ...plugins)
    }

    private createTransform(rootDir: string): ITransform {
        const { plugins, fs: fileSystem, logger, diagnostics, transform } = this.rootProject.getContext()
        return new Transform(
            new Project({ rootDir, plugins, fileSystem, logger, diagnostics, transform }),
            this.pluginUsageTracker
        )
    }

    private getFallbackTransform(): ITransform {
        return (this.fallbackTransform ??= this.createTransform(this.rootProject.getRootDir()))
    }

    private getTransformForPath(filePath: string): ITransform {
        if (this.transformMap[filePath]) {
            return this.transformMap[filePath]
        }

        // If it's in the root project's files, it must've been added explicitly regardless of path
        if (this.rootProject.getFileIfExists(filePath)) {
            return (this.transformMap[filePath] = this.rootTransform)
        }

        const projectRoot = this.findProjectRootForPath(filePath)
        if (projectRoot && this.transformMap[projectRoot]) {
            return this.transformMap[projectRoot]
        }

        if (!projectRoot) {
            return this.getFallbackTransform()
        }

        return (this.transformMap[projectRoot] = this.createTransform(projectRoot))
    }

    private findProjectRootForPath(filePath: string): string | undefined {
        if (this.isProjectRoot(filePath)) {
            return filePath
        }

        const parent = path.dirname(filePath)
        if (parent === filePath) {
            return undefined
        }

        return this.findProjectRootForPath(parent)
    }

    private readonly isProjectRootCache: { [filePath: string]: boolean } = {}
    private isProjectRoot(filePath: string): boolean {
        if (typeof this.isProjectRootCache[filePath] === 'boolean') {
            return this.isProjectRootCache[filePath]
        }

        const nowConfigPath = path.join(filePath, 'now.config.json')
        return (this.isProjectRootCache[filePath] =
            filePath in this.transformMap ||
            !!this.rootProject.getCompiler().getSourceFile(nowConfigPath) ||
            FileSystem.existsSync(this.rootProject.getFileSystem(), nowConfigPath))
    }
}
